import{_ as t}from"./chunks/architecture.Cs8uKTTN.js";import{_ as r,o as n,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"swag2mcp","description":"","frontmatter":{},"headers":[],"relativePath":"de/index.md","filePath":"de/index.md","lastUpdated":1784903584000}'),s={name:"de/index.md"};function d(o,e,h,l,c,p){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="swag2mcp" tabindex="-1">swag2mcp <a class="header-anchor" href="#swag2mcp" aria-label="Permalink to &quot;swag2mcp&quot;">​</a></h1><div style="background:#dc2626;color:white;padding:20px 24px;border-radius:12px;text-align:center;font-size:1.4em;font-weight:700;margin:24px 0;"> 🚧 IN ARBEIT — Veröffentlichung bald! </div><p>Verbindet OpenAPI/Swagger/Postman-API-Spezifikationen mit LLM-Agenten über das Model Context Protocol (MCP).</p><a href="https://www.youtube.com/watch?v=1Da4UmE2f9U" target="_blank"><img src="https://raw.githubusercontent.com/mmadfox/swag2mcp/main/docs/cover.png" alt="Vorschau"></a><h2 id="ihre-api-spricht-llm" tabindex="-1">Ihre API spricht LLM <a class="header-anchor" href="#ihre-api-spricht-llm" aria-label="Permalink to &quot;Ihre API spricht LLM&quot;">​</a></h2><p>Eine einzige Konfigurationszeile verwandelt jede OpenAPI/Swagger/Postman-Datei in einen MCP-Server. LLM-Agenten entdecken, inspizieren und rufen Ihre APIs auf — null Integrationscode.</p><img src="'+t+'" width="700" alt="swag2mcp-Architektur"><h2 id="schluss-mit-wrappern" tabindex="-1">Schluss mit Wrappern <a class="header-anchor" href="#schluss-mit-wrappern" aria-label="Permalink to &quot;Schluss mit Wrappern&quot;">​</a></h2><p>Jedes Mal, wenn Sie eine neue API mit einem LLM verbinden, schreiben Sie denselben Boilerplate-Code: Spezifikationsparsing, Authentifizierung, Fehlerbehandlung, Ratenbegrenzung. swag2mcp erledigt das für Sie — 19 vorgefertigte MCP-Tools.</p><h2 id="wer-braucht-das" tabindex="-1">Wer braucht das? <a class="header-anchor" href="#wer-braucht-das" aria-label="Permalink to &quot;Wer braucht das?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rolle</th><th>Warum</th></tr></thead><tbody><tr><td><strong>AI-Agent-Entwickler</strong></td><td>Jede API in 2 Minuten verbinden, nicht 2 Tage</td></tr><tr><td><strong>MCP-Ingenieur</strong></td><td>Kein Handler-Code — einfach auf eine Spezifikation verweisen</td></tr><tr><td><strong>Architekt</strong></td><td>Einheitliche API-Integrationsschicht für alle LLMs im Unternehmen</td></tr><tr><td><strong>Datenanalyst</strong></td><td>APIs per natürlicher Sprache nutzen, ohne Programmierung</td></tr><tr><td><strong>DevOps / SRE</strong></td><td>Überwachung und Automatisierung durch LLM ohne zusätzliche Dienste</td></tr><tr><td><strong>Integrator</strong></td><td>9 Authentifizierungsmethoden sofort einsatzbereit — Basic bis OAuth2 bis HMAC</td></tr><tr><td><strong>QA-Ingenieur</strong></td><td>Mock-Server für isolierte Tests ohne echte APIs</td></tr><tr><td><strong>Produktmanager</strong></td><td>Schnelle KI-Feature-Prototypen ohne Backend-Arbeit</td></tr><tr><td><strong>und viele weitere</strong></td><td></td></tr></tbody></table><hr><h2 id="lizenz" tabindex="-1">Lizenz <a class="header-anchor" href="#lizenz" aria-label="Permalink to &quot;Lizenz&quot;">​</a></h2><p>Lizenziert unter der <strong>GNU Affero General Public License v3.0</strong> (AGPL v3).</p><p>Siehe <a href="https://github.com/mmadfox/swag2mcp/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a> für den vollständigen Lizenztext.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SPDX-License-Identifier: AGPL-3.0-only</span></span></code></pre></div>',16)])])}const b=r(s,[["render",d]]);export{m as __pageData,b as default};
